const leads = $json.body?.leads ?? [];

function toText(value) {
  if (value === null || value === undefined) return null;

  if (Array.isArray(value)) {
    return value
      .map(v => typeof v === 'object' ? JSON.stringify(v) : String(v))
      .filter(Boolean)
      .join(', ') || null;
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value);
}

return leads.map(c => {

  const cf = c.custom_fields ?? {};

  return {
    json: {

      // =============================================
      // IDENTIFICAÇÃO
      // =============================================

      uuid: c.uuid ?? null,

      name: c.name ?? null,
      email: c.email ?? null,

      phone: c.phone ?? null,
      personal_phone: c.personal_phone ?? null,
      mobile_phone: c.mobile_phone ?? null,

      job_title: c.job_title ?? null,

      // Não existem no webhook atual
      birthdate: null,

      bio: c.bio ?? null,
      website: c.website ?? null,

      city: c.city ?? null,
      state: c.state ?? null,

      // Não existem no webhook atual
      country: null,

      twitter: null,
      facebook: null,
      linkedin: null,

      tags: toText(c.tags),

      // Não existe no webhook atual
      extra_emails: null,

      // =============================================
      // LEGAL BASIS
      // Não vem nesse webhook
      // =============================================

      legal_basis_category: null,
      legal_basis_type: null,
      legal_basis_status: null,

      // =============================================
      // LINKS API
      // Não precisamos consultar novamente o contato
      // =============================================

      self_uuid_url: null,
      self_email_url: null,
      self_phone_url: null,

      events_url: null,
      funnel_url: null,

      // =============================================
      // DATAS
      // =============================================

      created_at:
        c.created_at ?? null,

      last_conversion_date:
        c.last_conversion?.created_at ??
        c.last_conversion?.content?.event_timestamp ??
        null,

      // =============================================
      // CAMPOS PERSONALIZADOS
      // Mapeados para as colunas atuais do Azure
      // =============================================

      cf_ja_e_cliente_demo:
        toText(cf["Já é cliente DEMO?"]),

      cf_ferramenta:
        toText(cf["Ferramenta"]),

      cf_procura:
        toText(cf["Procura"]),

      cf_origem_do_lead_legado:
        toText(cf["Origem do lead - Legado"]),

      cf_agendamento:
        toText(cf["Agendamento"]),

      cf_origem_do_lead:
        toText(cf["Origem lead"]),

      cf_mensagem:
        toText(cf["Mensagem"]),

      cf_qual_produto_da_demo_mais_te_interessou:
        toText(cf["Qual produto da DEMO mais te interessou?"]),

      cf_url_do_arquivo:
        toText(cf["URL do arquivo"]),

      cf_informacao_importante:
        null,

      cf_canal:
        toText(cf["Canal"]),

      cf_cargo:
        toText(cf["Cargo:*"]),

      cf_consultor_a:
        toText(cf["Responsável"]),

      cf_voce_ja_conhece_a_demo:
        toText(cf["Qual é o seu vínculo com a DEMO?"]),

      cf_obs:
        toText(cf["Obs"]),

      cf_segmentos:
        toText(cf["Segmentos"]),

      cf_totem_segmento:
        toText(cf["segmento"]),

      cf_hub_id_do_registro:
        toText(cf["Hub_Pipedrive"]),

      cf_observacao_hub:
        toText(cf["Observação - HUB"])

    }
  };
});

const leads = $json.body?.leads ?? [];

const resultado = [];
const chaves = new Set();

for (const lead of leads) {

  const uuid = String(lead.uuid ?? '')
    .trim()
    .toLowerCase();

  if (!uuid) continue;

  const conversao = lead.last_conversion;

  if (!conversao) continue;

  const content = conversao.content ?? {};
  const original = content.__cdp__original_event ?? {};

  const eventType =
    original.event_type ??
    content.event_type ??
    'CONVERSION';

  const eventFamily =
    original.event_family ??
    'CDP';

  const eventIdentifier =
    original.event_identifier ??
    content.event_identifier ??
    content.conversion_identifier ??
    content.identificador ??
    conversao.source ??
    null;

  // IMPORTANTE:
  // prioriza a data externa da conversão,
  // que é a mesma utilizada no histórico
  const eventTimestamp =
    conversao.created_at ??
    original.event_timestamp ??
    content.event_timestamp ??
    content.created_at ??
    null;

  const email =
    String(
      original.payload?.email ??
      content.email_lead ??
      lead.email ??
      ''
    )
      .trim()
      .toLowerCase() || null;

  if (!eventIdentifier || !eventTimestamp) {
    continue;
  }

  // Se existir payload CDP usa ele.
  // Caso contrário monta o payload com os dados do webhook.
  const payload =
  original.payload ??
  {
    name:
      content.nome ??
      content.Nome ??
      lead.name ??
      null,

    email:
      content.email_lead ??
      lead.email ??
      null,

    company_name:
      content.empresa ??
      content.Empresa ??
      lead.company ??
      null,

    personal_phone:
      content.telefone ??
      content.Telefone ??
      lead.personal_phone ??
      lead.phone ??
      null,

    job_title:
      content.cargo ??
      content.Cargo ??
      lead.job_title ??
      null,

    conversion_identifier:
      content.conversion_identifier ??
      content.event_identifier ??
      content.identificador ??
      null,

    traffic_source:
      content.traffic_source ??
      null,

    traffic_medium:
      content.traffic_medium ??
      null,

    traffic_campaign:
      content.traffic_campaign ??
      null,

    traffic_channel:
      content.traffic_channel ??
      null,

    traffic_term:
      content.traffic_term ??
      null
  };

  const eventKeySource = [
    uuid,
    eventType,
    eventIdentifier,
    eventTimestamp
  ].join('|');

  if (chaves.has(eventKeySource)) {
    continue;
  }

  chaves.add(eventKeySource);

  resultado.push({
    json: {
      contact_uuid: uuid,
      contact_email: email,

      event_type: eventType,
      event_family: eventFamily,
      event_identifier: eventIdentifier,
      event_timestamp: eventTimestamp,
      traffic_source: payload.traffic_source ?? null,
      event_key_source: eventKeySource,
      payload_json: JSON.stringify(payload)
    }
  });
}

return resultado;
